from collections import defaultdict


def group_order_ids_by_status(orders: list[dict]) -> dict[str, list[str]]:
    groups = defaultdict(list)
    for order in orders:
        status = (order.get("status") or "").strip().lower() or "unknown"
        groups[status].append(order["order_id"])
    return dict(groups)
